  "landing.faq.title": "คำถามที่พบบ่อย",
  "landing.faq.q1": "Second Brain เป็นแค่แชทบอตใช่ไหม?",
  "landing.faq.a1": "ไม่ใช่ มันคือสภาพแวดล้อมการเรียนรู้ส่วนบุคคล: ทำความเข้าใจเนื้อหาของคุณ สอนคุณ และจดจำความก้าวหน้าของคุณไปตามกาลเวลา",
  "landing.faq.q2": "ฉันสามารถทำงานกับ PDF และเอกสารหลายฉบับได้ไหม?",
  "landing.faq.a2": "ได้ คุณสามารถจัดกลุ่ม PDF รูปภาพ เอกสารสแกน และบันทึกต่างๆ เป็นวิชาเดียว และเรียนรู้จากชุดข้อมูลทั้งหมด ไม่ใช่แค่ไฟล์เดียว",
  "landing.faq.q3": "ฉันทำอะไรกับ AI Professor ได้บ้าง?",
  "landing.faq.a3": "รับการสอน ขอคำอธิบาย อภิปราย ทำเซสชันแนะนำ และฝึกฝนด้วยแบบฝึกหัดที่ปรับให้เข้ากับระดับของคุณ",
  "landing.faq.q4": "ฉันคุยกับ AI Professor ออกเสียงได้ไหม",
  "landing.faq.a4": "ได้ การสนทนาด้วยเสียง แบบฝึกหัดการพูด และการสอบปากเปล่าช่วยให้คุณฝึกฝนเปล่งเสียงได้",
  "landing.faq.q5": "Digital Twin คืออะไร",
  "landing.faq.a5": "ความจำส่วนบุคคลเกี่ยวกับการเรียนรู้ของคุณ ทั้งสิ่งที่คุณเข้าใจ เชี่ยวชาญ ลืม และเป้าหมายของคุณ",
  "landing.faq.q6": "ความจำและการทบทวนทำงานอย่างไร",
  "landing.faq.a6": "ระบบเว้นระยะการทบทวน (FSRS) จะจัดตารางการทบทวนในเวลาที่เหมาะสม ช่วยให้คุณจำได้มากขึ้นโดยใช้ความพยายามน้อยลง",
  "landing.faq.q7": "ฉันใช้ Second Brain สำหรับงานวิชาการได้ไหม",
  "landing.faq.a7": "ได้ Academic Workspace ช่วยแนะนำการทำแลป การบ้าน รายงาน และอื่นๆ โดยสอนวิธีทำ ไม่ใช่แค่บอกคำตอบ",
  "landing.faq.q8": "การเรียนภาษาทำงานอย่างไร",
  "landing.faq.a8": "การดื่มด่ำทางภาษา การสนทนา การฝึกพูด และการทำ Shadowing รวมถึงช่วยทำความเข้าใจภาษาในหลักสูตรของคุณเอง",
  "landing.faq.q9": "ข้อมูลของฉันได้รับการปกป้องอย่างไร",
  "landing.faq.a9": "ข้อมูลการเรียนรู้ของคุณช่วยขับเคลื่อนประสบการณ์ของคุณ คุณควบคุมบัญชีของคุณได้และจัดการข้อมูลได้จากโปรไฟล์",
