  "landing12.faq.title": "มีคำถามหรือ เรามีคำตอบ",
  "landing12.faq.lead": "คำตอบสั้น ๆ เกี่ยวกับสิ่งที่ผลิตภัณฑ์ทำได้จริงในวันนี้",
  "landing12.faq.q1": "Second Brain คืออะไร",
  "landing12.faq.a1": "ระบบการเรียนรู้อัจฉริยะส่วนบุคคลที่เชื่อมคำถาม แหล่งข้อมูล การสอน การฝึกฝน ความจำ และงานวิชาการไว้ในบริบทเดียว",
  "landing12.faq.q2": "เป็นเพียงแชตบอตใช่หรือไม่",
  "landing12.faq.a2": "ไม่ใช่ การสนทนาเป็นเพียงส่วนติดต่อหนึ่ง เซสชันเดียวกันสามารถเปลี่ยนเป็นบทเรียน แบบฝึกพูด คำถามที่อ้างอิงเอกสาร การทบทวน หรือการดำเนินการในพื้นที่ทำงานได้",
  "landing12.faq.q3": "สมองของฉันทำงานอย่างไร",
  "landing12.faq.a3": "พื้นที่นี้ทำให้แนวคิด ความสัมพันธ์ หลักฐานความเชี่ยวชาญ ความจำ และประวัติการเรียนรู้ของคุณมองเห็นได้ พร้อมปรับมุมมองตามความสมบูรณ์ของข้อมูลที่มี",
  "landing12.faq.q4": "ฉันใช้เอกสารของตนเองได้หรือไม่",
  "landing12.faq.a4": "ได้ คลังรองรับไฟล์และเอกสารสแกนในรูปแบบที่รองรับ แสดงสถานะการประมวลผลจริง แยกแนวคิด และรองรับคำถามกับการแปลงเนื้อหาที่อิงแหล่งข้อมูล",
  "landing12.faq.q5": "ฉันเรียนภาษาได้หรือไม่",
  "landing12.faq.a5": "ได้ กลไกภาษาในชีวิตจริงผสานหลักสูตร CEFR การเรียนภาษาอย่างชัดเจน ภารกิจทั่วโลก การฝึกพูด การแก้จุดอ่อนแบบเจาะจง การทบทวน และหลักฐานสิ่งที่ทำได้",
  "landing12.faq.q6": "อาจารย์ AI ทำงานอย่างไร",
  "landing12.faq.a6": "อาจารย์ใช้บริบทปัจจุบันของผู้เรียน และสามารถอธิบาย สอน ตั้งคำถาม ประเมิน หรือฝึกฝน พร้อมรักษาเซสชันประสบการณ์ไว้",
  "landing12.faq.q7": "การทบทวนทำงานอย่างไร",
  "landing12.faq.a7": "การทบทวนใช้ประวัติจริงและการทบทวนแบบเว้นระยะ เพื่อจัดลำดับความรู้ที่เสี่ยงจะถูกลืม การทบทวนที่ไม่ใช้ AI ยังคงใช้งานได้โดยไม่ขึ้นกับโควตา AI",
  "landing12.faq.q8": "มีภาษาใดให้ใช้งานบ้าง",
  "landing12.faq.a8": "ขณะนี้ทะเบียนที่ใช้ร่วมกันมีภาษาสำหรับการเรียนรู้ 34 ภาษา ภาษาของส่วนติดต่อและภาษาที่เรียนเป็นตัวเลือกที่แยกจากกันเสมอ",
  "landing12.faq.q9": "การวิจัยค้นหาในเว็บหรือไม่",
  "landing12.faq.a9": "ปัจจุบันการวิจัยทำงานกับสมองของฉันและคลังของคุณได้ แต่การติดตั้งใช้งานปัจจุบันยังไม่ได้กำหนดค่าผู้ให้บริการเว็บภายนอก หน้าเริ่มต้นจึงไม่อ้างว่าทำได้",
  "landing12.faq.q10": "ข้อมูลของฉันเป็นส่วนตัวหรือไม่",
  "landing12.faq.a10": "การควบคุมสำหรับผู้ที่เข้าสู่ระบบครอบคลุมหน่วยความจำ AI เอกสาร ความยินยอม การส่งออก และการลบบัญชี หน้านี้ไม่ได้เพิ่มคำมั่นทางกฎหมายหรือโครงสร้างพื้นฐานนอกเหนือจากการควบคุมเหล่านั้น",
  "landing12.faq.q11": "Free, Pro และ Max แตกต่างกันอย่างไร",
  "landing12.faq.a11": "ทั้งสามคือระดับแผนรายบุคคลในแค็ตตาล็อกของแบ็กเอนด์ ราคา โควตา และสิทธิประโยชน์ของแผนขั้นสุดท้ายจะกำหนดหลังช่วงเบต้าสาธารณะ",
  "landing12.faq.q12": "ฉันใช้ Second Brain ได้ที่ไหน",
